import os, json, pickle
from pathlib import Path
import numpy as np
from scipy import io as spio

root = Path('data')
print('TOP_LEVEL:', sorted([p.name for p in root.iterdir()]))
for p in sorted(root.rglob('*')):
    if p.is_file():
        print(f'FILE {p} size={p.stat().st_size}')
        suf = p.suffix.lower()
        try:
            if suf == '.npy':
                arr = np.load(p, allow_pickle=True)
                if isinstance(arr, np.ndarray):
                    print('  NPY dtype=', arr.dtype, 'shape=', arr.shape)
                    if arr.dtype == object and arr.shape == ():
                        obj = arr.item()
                        print('  NPY object type=', type(obj).__name__)
                        if isinstance(obj, dict):
                            print('  keys=', sorted(map(str, obj.keys()))[:40])
                else:
                    print('  NPY type=', type(arr).__name__)
            elif suf == '.npz':
                z = np.load(p, allow_pickle=True)
                print('  NPZ keys=', list(z.keys()))
                for k in list(z.keys())[:20]:
                    print('   ', k, z[k].shape, z[k].dtype)
            elif suf == '.mat':
                m = spio.loadmat(p, simplify_cells=False)
                keys = [k for k in m.keys() if not k.startswith('__')]
                print('  MAT keys=', keys[:40])
                for k in keys[:10]:
                    v = m[k]
                    print('   ', k, type(v).__name__, getattr(v, 'shape', None), getattr(v, 'dtype', None))
            elif suf in ('.pkl', '.pickle'):
                with open(p, 'rb') as f:
                    obj = pickle.load(f)
                print('  PKL type=', type(obj).__name__)
                if isinstance(obj, dict):
                    print('  keys=', sorted(map(str, obj.keys()))[:40])
            elif p.name.lower().startswith('readme') or suf in ('.txt', '.csv', '.tsv'):
                with open(p, 'r', errors='ignore') as f:
                    head = ''.join([next(f) for _ in range(5)])
                print('  HEAD:\n' + head)
        except Exception as e:
            print('  INSPECT_ERROR', type(e).__name__, e)
